// Python encodings/punycode.py port
function T(j,bias){let res=36*(j+1)-bias; if(res<1)return 1; if(res>26)return 26; return res;}
function adapt(delta, first, numchars){
  if(first) delta = Math.floor(delta/700); else delta = Math.floor(delta/2);
  delta += Math.floor(delta/numchars);
  let divisions=0;
  while(delta>455){ delta=Math.floor(delta/35); divisions+=36; }
  return divisions + Math.floor((36*delta)/(delta+38));
}
function generate_integers(baselen, deltas){
  // python: for points in deltas: generate_generalized_integer
  let out=[]; let bias=72;
  for(let i=0;i<deltas.length;i++){
    out.push(generate_generalized_integer(deltas[i],bias));
    bias = adapt(deltas[i], i===0, baselen+i+1);
  }
  return out.join('');
}
const digits="abcdefghijklmnopqrstuvwxyz0123456789";
function generate_generalized_integer(N,bias){
  let result=""; let j=0;
  while(true){ let t=T(j,bias); if(N<t){ result+=digits[N]; return result;} result+=digits[t+((N-t)%(36-t))]; N=Math.floor((N-t)/(36-t)); j++; }
}
// decode side
function decode_generalized_number(extended, extpos, bias){
  let result=0,w=1,j=0;
  while(true){
    if(extpos>=extended.length) throw new Error("incomplete punycode string");
    let char=extended.charCodeAt(extpos); extpos++;
    let digit;
    if(char>=0x41&&char<=0x5A) digit=char-0x41;
    else if(char>=0x30&&char<=0x39) digit=char-22;
    else throw new Error("Invalid extended code point '"+extended[extpos-1]+"'");
    let t=T(j,bias); result+=digit*w;
    if(digit<t) return [extpos,result];
    w=w*(36-t); j++;
  }
}
function insertion_sort(base, extended){
  let char=0x80,pos=-1,bias=72,extpos=0;
  let arr=Array.from(base);
  while(extpos<extended.length){
    let [newpos,delta]=decode_generalized_number(extended,extpos,bias);
    pos+=delta+1;
    char+=Math.floor(pos/(arr.length+1));
    if(char>0x10FFFF) throw new Error("Invalid character U+"+char.toString(16));
    pos=pos%(arr.length+1);
    arr.splice(pos,0,char);
    bias=adapt(delta,(extpos===0),arr.length);
    extpos=newpos;
  }
  return arr;
}
function pyDecode(text){
  let p=text.lastIndexOf('-'); let base,extended;
  if(p===-1){base="";extended=text.toUpperCase();}
  else {base=text.slice(0,p); extended=text.slice(p+1).toUpperCase();}
  return insertion_sort(base,extended);
}
// encode a list of codepoints (python punycode_encode)
function pyEncode(cps){
  let base=[],extended=[];
  for(const c of cps){ if(c<128) base.push(c); else extended.push(c); }
  extended=[...new Set(extended)].sort((a,b)=>a-b);
